INSERT INTO configuracion_sistema (clave, categoria, descripcion, valor, usuario_modificacion, fecha_modificacion) VALUES ('niveles_solicitante_config', 'MESA_SERVICIO', 'Matriz de privilegios, visualización y acciones por nivel institucional de solicitante (1 a 5)', '{"1":{"puede_editar_sla":false,"puede_reabrir_ticket":true,"prioridad_base_minima":"p2_alta","puede_cancelar_ticket":true,"puede_crear_para_otros":true,"ver_historial_auditoria":true,"ver_comunicacion_interna":true,"ver_panel_cmdb_detallado":true,"ver_temporizador_costos_sla":true},"2":{"puede_editar_sla":false,"puede_reabrir_ticket":true,"prioridad_base_minima":"p2_alta","puede_cancelar_ticket":true,"puede_crear_para_otros":true,"ver_historial_auditoria":true,"ver_comunicacion_interna":true,"ver_panel_cmdb_detallado":true,"ver_temporizador_costos_sla":true},"3":{"puede_editar_sla":false,"puede_reabrir_ticket":true,"prioridad_base_minima":"p3_media","puede_cancelar_ticket":true,"puede_crear_para_otros":true,"ver_historial_auditoria":true,"ver_comunicacion_interna":true,"ver_panel_cmdb_detallado":true,"ver_temporizador_costos_sla":false},"4":{"puede_editar_sla":true,"puede_reabrir_ticket":true,"prioridad_base_minima":"automatica","puede_cancelar_ticket":true,"puede_crear_para_otros":true,"ver_historial_auditoria":true,"ver_comunicacion_interna":true,"ver_panel_cmdb_detallado":true,"ver_temporizador_costos_sla":true},"5":{"puede_editar_sla":false,"puede_reabrir_ticket":true,"prioridad_base_minima":"automatica","puede_cancelar_ticket":true,"puede_crear_para_otros":false,"ver_historial_auditoria":false,"ver_comunicacion_interna":false,"ver_panel_cmdb_detallado":false,"ver_temporizador_costos_sla":false}}'::jsonb, 1, '2026-11-10T06:33:54.932Z');
INSERT INTO configuracion_sistema (clave, categoria, descripcion, valor, usuario_modificacion, fecha_modificacion) VALUES ('plantillas_correo_html', 'NOTIFICACIONES', 'Plantillas HTML y diseño corporativo de correos del sistema', '{"logo_url":"https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=160&auto=format&fit=crop&q=80","plantillas":{"cambio_cab":{"asunto":"Convocatoria CAB para Solicitud de Cambio: [{{codigo_cambio}}]","cuerpo":"Estimado Miembro del CAB,\n\nSe ha programado una solicitud de cambio que requiere evaluación de contingencias y análisis de impacto en la infraestructura.","encabezado":"Revisión y Dictamen Colegiado del Comité CAB","destinatarios":{"cab":true,"tecnico":true,"supervisor":true,"solicitante":false}},"ticket_creado":{"asunto":"Ticket Registrado: [{{codigo_ticket}}] {{titulo}}","cuerpo":"Estimado/a {{solicitante_nombre}},\n\nHemos recibido satisfactoriamente su requerimiento en la Mesa de Servicio. Un especialista asignado procederá a su atención dentro del plazo comprometido por el acuerdo de nivel de servicio (SLA).\n\nPuede consultar el avance y la línea de tiempo en el portal.","encabezado":"Su requerimiento ha sido registrado formalmente","destinatarios":{"tecnico":false,"supervisor":true,"solicitante":true}},"ticket_resuelto":{"asunto":"Ticket Resuelto: [{{codigo_ticket}}] {{titulo}}","cuerpo":"Estimado/a {{solicitante_nombre}},\n\nLe informamos que el caso {{codigo_ticket}} ha sido resuelto por el equipo técnico resolutor.\n\nPor favor ingrese al sistema para calificar el servicio y confirmar el cierre definitivo del caso.","encabezado":"El servicio ha sido restablecido","destinatarios":{"tecnico":true,"supervisor":true,"solicitante":true}}},"color_primario":"#2563eb","nombre_empresa":"Sistema Institucional de Gestión de Servicios TI"}'::jsonb, 1, '2026-09-30T17:13:19.094Z');
